"""langpacks: the language packs of an owner's catalogs, and the openmixer meta packs (Open-Mixer/.github#37).

An owner keeps one catalog per language, catalogs/<lang>.json, installed at /usr/share/<owner>/catalogs/<lang>.json.
Each listed language (omx-contract's languages.json, its "languages") becomes one pack built from the owner's own spec and debian/,
from the same source commit: rpm <name>-langpack-<lang> (noarch, Supplements: (<base> and langpacks-<lang>)) and deb
<name>-l10n-<lang> (Architecture: all, Section: localization, Depends: <base> (= ${source:Version})), each
owning exactly its catalog; a language that moves out of <base> (--moved <lang>:<version>) Breaks and Replaces
<base> (<< <version>~). The generated text sits
between two marker lines in the spec and in debian/control, and the .install files beside them; --check holds them to
what this writes. A listed language with no catalog file is refused, and so is a catalog of a language the list does not
name: never an empty pack, never a pack nobody asked for. What a catalog holds (its keys, placeholders and stale
entries) is omx-contract's release gate, `omx-contract translate --check`, never this.

The meta packs, openmixer-langpack-<lang> and openmixer-l10n-<lang>, require every listed owner's pack for their
language: an owner whose pack is not in the channel leaves the meta pack uninstallable, which the channel check reads.

  langpacks.py rpm  --spec <spec> --name <pkg> [--base <pkg>] --owner <dir> --catalogs <dir> --languages <file> [--check]
  langpacks.py deb  --debian <dir> --name <pkg> [--base <pkg>] --owner <dir> --catalogs <dir> --languages <file> [--check]
  langpacks.py meta --spec <spec> --debian <dir> --owners <file> --languages <file> [--check]

<file> of languages is omx-contract's languages.json; the languages are its "languages" list. <file> of owners holds one
owner per line, its rpm pack prefix then its deb pack prefix ('#' starts a comment). Exit 0 when current (or written),
1 when --check finds a file stale or a catalog missing, 2 on a usage error.
"""
import argparse
import json
import os
import sys
import textwrap

LISTED = "languages"
BEGIN = "# BEGIN langpacks: generated by langpacks.py, do not edit"
END = "# END langpacks"


class Refused(Exception):
    pass


def languages(path):
    with open(path) as f:
        doc = json.load(f)
    langs = doc.get(LISTED)
    if not isinstance(langs, list) or not langs or not all(isinstance(x, str) and x for x in langs):
        raise Refused("%s: no %r list of language codes" % (path, LISTED))
    if len(set(langs)) != len(langs):
        raise Refused("%s: a language is listed twice" % path)
    return langs


def catalogs_for(catalogs, langs):
    """the listed languages, each with its catalog file; a missing file or an unlisted one is refused"""
    have = sorted(f[:-5] for f in os.listdir(catalogs) if f.endswith(".json")) if os.path.isdir(catalogs) else []
    missing = [x for x in langs if x not in have]
    extra = [x for x in have if x not in langs]
    problems = []
    if missing:
        problems.append("no catalog for %s (%s/<lang>.json)" % (", ".join(missing), catalogs))
    if extra:
        problems.append("%s/%s is a language the list does not ship" % (catalogs, ", ".join(x + ".json" for x in extra)))
    if problems:
        raise Refused("; ".join(problems))
    return langs


def describe(name, lang):
    return ("The sentences of %s's codes in the language %s, read by every surface that shows them on a host in "
            "that locale; without it a surface shows the English source sentence." % (name, lang))


def rpm_block(name, base, owner, langs):
    out = []
    for lang in langs:
        out += [
            "%%package langpack-%s" % lang,
            "Summary: The %s catalog of %s's codes" % (lang, name),
            "BuildArch: noarch",
            "Requires: %s = %%{version}-%%{release}" % base,
            "Supplements: (%s and langpacks-%s)" % (base, lang),
            "",
            "%%description langpack-%s" % lang,
        ] + textwrap.wrap(describe(name, lang), 79) + [
            "",
            "%%files langpack-%s" % lang,
            "%%{_datadir}/%s/catalogs/%s.json" % (owner, lang),
            "",
        ]
    return out


def deb_block(name, base, langs, moved):
    out = []
    for lang in langs:
        out += [
            "Package: %s-l10n-%s" % (name, lang),
            "Section: localization",
            "Architecture: all",
            "Depends: %s (= ${source:Version}), ${misc:Depends}" % base,
        ]
        if lang in moved:
            out += ["Breaks: %s (<< %s~)" % (base, moved[lang]), "Replaces: %s (<< %s~)" % (base, moved[lang])]
        out += [
            "Description: %s catalog of %s's codes" % (lang, name),
        ] + [" " + line for line in textwrap.wrap(describe(name, lang), 78)] + [
            "",
        ]
    return out


def meta_rpm_block(owners, langs):
    out = []
    for lang in langs:
        out += ["%%package -n openmixer-langpack-%s" % lang,
                "Summary: Every OpenMixer catalog in the language %s" % lang,
                "BuildArch: noarch"]
        out += ["Requires: %s-langpack-%s" % (rpm, lang) for rpm, _ in owners]
        out += ["Supplements: langpacks-%s" % lang, "",
                "%%description -n openmixer-langpack-%s" % lang,
                "Pulls the %s catalog of every OpenMixer owner of codes." % lang, "",
                "%%files -n openmixer-langpack-%s" % lang, ""]
    return out


def meta_deb_block(owners, langs):
    out = []
    for lang in langs:
        out += ["Package: openmixer-l10n-%s" % lang,
                "Architecture: all",
                "Section: metapackages",
                "Depends: %s, ${misc:Depends}" % ", ".join("%s-l10n-%s" % (deb, lang) for _, deb in owners),
                "Description: every OpenMixer catalog in the language %s" % lang,
                " Pulls the %s catalog of every OpenMixer owner of codes." % lang,
                ""]
    return out


def splice(text, block, where):
    """text with the lines between the markers replaced by block; the markers must be there once each"""
    lines = text.split("\n")
    if lines.count(BEGIN) != 1 or lines.count(END) != 1:
        raise Refused("%s: the lines %r and %r must each appear once" % (where, BEGIN, END))
    b, e = lines.index(BEGIN), lines.index(END)
    if e < b:
        raise Refused("%s: %r comes before %r" % (where, END, BEGIN))
    while block and block[-1] == "":
        block = block[:-1]
    return "\n".join(lines[:b + 1] + block + lines[e:])


class Files:
    """the files a run writes, or, with check, compares"""

    def __init__(self, check):
        self.check, self.stale = check, []

    def put(self, path, text):
        old = open(path).read() if os.path.exists(path) else None
        if old == text:
            return
        if self.check:
            self.stale.append(path)
        else:
            with open(path, "w") as f:
                f.write(text)

    def splice(self, path, block):
        self.put(path, splice(open(path).read(), block, path))

    def done(self):
        for p in self.stale:
            print("langpacks: %s is not what langpacks.py writes: run it without --check" % p, file=sys.stderr)
        return 1 if self.stale else 0


OVERRIDES = ("# published by the OpenMixer channel, not uploaded to Debian (written by langpacks.py)\n"
             "%s: initial-upload-closes-no-bugs\n")


def license_lines(control):
    """the SPDX and Copyright lines debian/control starts with: the generated files carry the tree's own"""
    out = []
    for line in open(control).read().split("\n"):
        if not line.startswith("#"):
            break
        if line.startswith(("# SPDX-License-Identifier:", "# Copyright")):
            out.append(line + "\n")
    return "".join(out)


def deb_files(files, debian, prefix, langs, installs):
    """each pack's .install (when it installs a file) and .lintian-overrides beside debian/control, under the license
    lines of debian/control; one of a language the list does not ship is stale"""
    head = license_lines(os.path.join(debian, "control"))
    want = {}
    for lang in langs:
        pkg = "%s-l10n-%s" % (prefix, lang)
        if lang in installs:
            want[pkg + ".install"] = head + installs[lang]
        want[pkg + ".lintian-overrides"] = head + OVERRIDES % pkg
    for name, text in want.items():
        files.put(os.path.join(debian, name), text)
    for f in sorted(os.listdir(debian)):
        if f.startswith(prefix + "-l10n-") and f.endswith((".install", ".lintian-overrides")) and f not in want:
            print("langpacks: %s/%s is a language the list does not ship" % (debian, f), file=sys.stderr)
            files.stale.append(os.path.join(debian, f))


def owners_of(path):
    out = []
    for n, line in enumerate(open(path), 1):
        line = line.split("#", 1)[0].split()
        if not line:
            continue
        if len(line) != 2:
            raise Refused("%s:%d: an owner is its rpm pack prefix and its deb pack prefix" % (path, n))
        out.append((line[0], line[1]))
    if not out:
        raise Refused("%s: no owner" % path)
    return out


def main(argv):
    ap = argparse.ArgumentParser(prog="langpacks.py", description=__doc__.split("\n")[0])
    ap.add_argument("kind", choices=["rpm", "deb", "meta"])
    ap.add_argument("--spec")
    ap.add_argument("--debian")
    ap.add_argument("--name")
    ap.add_argument("--base")
    ap.add_argument("--owner")
    ap.add_argument("--catalogs")
    ap.add_argument("--owners")
    ap.add_argument("--languages", required=True)
    ap.add_argument("--check", action="store_true")
    ap.add_argument("--moved", action="append", default=[], metavar="LANG:VERSION",
                    help="a language whose catalog <base> carried before VERSION, the first release with its pack")
    a = ap.parse_args(argv)
    need = {"rpm": ["spec", "name", "owner", "catalogs"], "deb": ["debian", "name", "owner", "catalogs"],
            "meta": ["spec", "debian", "owners"]}[a.kind]
    missing = [n for n in need if not getattr(a, n)]
    if missing:
        ap.error("%s needs %s" % (a.kind, ", ".join("--" + n for n in missing)))
    files = Files(a.check)
    try:
        langs = languages(a.languages)
        if a.kind == "meta":
            owners = owners_of(a.owners)
            files.splice(a.spec, meta_rpm_block(owners, langs))
            files.splice(os.path.join(a.debian, "control"), meta_deb_block(owners, langs))
            deb_files(files, a.debian, "openmixer", langs, {})
            return files.done()
        langs = catalogs_for(a.catalogs, langs)
        base = a.base or a.name
        if a.kind == "rpm":
            files.splice(a.spec, rpm_block(a.name, base, a.owner, langs))
        else:
            moved = {}
            for m in a.moved:
                lang, _, version = m.partition(":")
                if lang not in langs or not version:
                    raise Refused("--moved %s: a listed language and the first version with its pack" % m)
                moved[lang] = version
            files.splice(os.path.join(a.debian, "control"), deb_block(a.name, base, langs, moved))
            deb_files(files, a.debian, a.name, langs,
                      {lang: "usr/share/%s/catalogs/%s.json\n" % (a.owner, lang) for lang in langs})
        return files.done()
    except Refused as e:
        print("langpacks: %s" % e, file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
